#include <stdio.h>

int main(void) {
    int a, b;
    scanf("%d %d", &a, &b);

    /* C's / and % round toward zero; Python's // and % round toward negative infinity. */
    int q = a / b;
    if (a % b != 0 && ((a < 0) != (b < 0))) q--;
    int r = a - b * q;

    printf("Sum: %d\n", a + b);
    printf("Difference: %d\n", a - b);
    printf("Product: %d\n", a * b);
    printf("Division: %.2f\n", (double)a / b);
    printf("Floor Division: %d\n", q);
    printf("Modulus: %d\n", r);
    return 0;
}

