c.solution:
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
 * The shortest text that reads back as the same number, like Python's repr: plain
 * digits from 0.0001 up to 10^16, an exponent outside that.
 */
void shortest(double x, char *out) {
    for (int precision = 1; precision <= 17; precision++) {
        snprintf(out, 64, "%.*g", precision, x);
        if (strtod(out, NULL) != x) continue;
        double size = fabs(x);
        if (strchr(out, 'e') && size >= 1e-4 && size < 1e16) {
            int exponent = (int)floor(log10(size));
            int decimals = precision - 1 - exponent;
            snprintf(out, 64, "%.*f", decimals > 0 ? decimals : 0, x);
        }
        return;
    }
}

int main(void) {
    char text[128];
    if (scanf("%127s", text) != 1) return 0;

    /* "a+bj" or "a-bj": split at the sign before the imaginary part. */
    int at = 0;
    for (int i = 1; text[i]; i++) {
        if ((text[i] == '+' || text[i] == '-') && text[i - 1] != 'e') at = i;
    }
    double real = strtod(text, NULL);
    double imag = strtod(text + at, NULL);

    char r[64], im[64], conj[64];
    shortest(real, r);
    shortest(imag, im);
    shortest(fabs(imag), conj);

    printf("Type: complex\n");
    /* Python prints a whole float with ".0"; inside a complex number it doesn't. */
    printf("Real: %s%s\n", r, strpbrk(r, ".e") ? "" : ".0");
    printf("Imaginary: %s%s\n", im, strpbrk(im, ".e") ? "" : ".0");
    printf("Conjugate: (%s%c%sj)\n", r, -imag < 0 ? '-' : '+', conj);
    printf("Magnitude: %.2f\n", hypot(real, imag));
    return 0;
}

