#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <iostream>
#include <string>

// The shortest text that reads back as the same number, like Python's repr: plain
// digits from 0.0001 up to 10^16, an exponent outside that.
std::string shortest(double x) {
    char out[64];
    for (int precision = 1; precision <= 17; precision++) {
        std::snprintf(out, sizeof out, "%.*g", precision, x);
        if (std::strtod(out, nullptr) != x) continue;
        double size = std::fabs(x);
        if (std::string(out).find('e') != std::string::npos && size >= 1e-4 && size < 1e16) {
            int exponent = static_cast<int>(std::floor(std::log10(size)));
            int decimals = precision - 1 - exponent;
            std::snprintf(out, sizeof out, "%.*f", decimals > 0 ? decimals : 0, x);
        }
        break;
    }
    return out;
}

// Python prints a whole float with ".0"; inside a complex number it doesn't.
std::string as_float(double x) {
    std::string s = shortest(x);
    return s.find_first_of(".e") == std::string::npos ? s + ".0" : s;
}

int main() {
    std::string text;
    std::cin >> text;

    // "a+bj" or "a-bj": split at the sign before the imaginary part.
    std::size_t at = 0;
    for (std::size_t i = 1; i < text.size(); i++) {
        if ((text[i] == '+' || text[i] == '-') && text[i - 1] != 'e') at = i;
    }
    double real = std::stod(text.substr(0, at));
    double imag = std::stod(text.substr(at, text.size() - at - 1));

    std::cout << "Type: complex\n";
    std::cout << "Real: " << as_float(real) << "\n";
    std::cout << "Imaginary: " << as_float(imag) << "\n";
    std::cout << "Conjugate: (" << shortest(real) << (-imag < 0 ? '-' : '+') << shortest(std::fabs(imag)) << "j)\n";
    std::printf("Magnitude: %.2f\n", std::hypot(real, imag));
}

