import java.util.Scanner;

public class Main {
    // Java prints a double like Python's repr (3.0, -2.5); inside a complex number
    // Python drops a whole number's ".0".
    static String inComplex(double x) {
        String s = Double.toString(x);
        return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
    }

    public static void main(String[] args) {
        String text = new Scanner(System.in).next();

        // "a+bj" or "a-bj": split at the sign before the imaginary part.
        int at = 0;
        for (int i = 1; i < text.length(); i++) {
            char ch = text.charAt(i);
            if ((ch == '+' || ch == '-') && text.charAt(i - 1) != 'e') at = i;
        }
        double real = Double.parseDouble(text.substring(0, at));
        double imag = Double.parseDouble(text.substring(at, text.length() - 1));

        System.out.println("Type: complex");
        System.out.println("Real: " + real);
        System.out.println("Imaginary: " + imag);
        System.out.println("Conjugate: (" + inComplex(real) + (-imag < 0 ? "-" : "+") + inComplex(Math.abs(imag)) + "j)");
        System.out.printf("Magnitude: %.2f%n", Math.hypot(real, imag));
    }
}

