    if (d > 0) printf("Nature: Real and distinct\n");
    else if (d == 0) printf("Nature: Real and equal\n");
    else printf("Nature: Complex\n");

    if (d >= 0) {
        printf("Root 1: %.2f\n", (-b + sqrt(d)) / (2.0 * a));
        printf("Root 2: %.2f\n", (-b - sqrt(d)) / (2.0 * a));
    } else {
        /* Complex roots: real part -b/2a, imaginary part ±√(-d)/2a. */
        double real = -b / (2.0 * a);
        double imag = sqrt(-d) / (2.0 * a);
        printf("Root 1: %.2f%+.2fj\n", real, imag);
        printf("Root 2: %.2f%+.2fj\n", real, -imag);
    }
    return 0;
}

