#include <ctype.h>
#include <stdio.h>
#include <string.h>

int main(void) {
    char text[512], cleaned[512];
    if (!fgets(text, sizeof text, stdin)) return 0;

    int n = 0;
    for (int i = 0; text[i]; i++) {
        unsigned char ch = (unsigned char)text[i];
        if (isalnum(ch)) cleaned[n++] = (char)tolower(ch);
    }
    cleaned[n] = '\0';

    int palindrome = 1;
    for (int i = 0; i < n / 2; i++) {
        if (cleaned[i] != cleaned[n - 1 - i]) palindrome = 0;
    }

    printf("Cleaned: %s\n", cleaned);
    printf(palindrome ? "Palindrome\n" : "Not a palindrome\n");
    return 0;
}

