#include <stdio.h>
#include <string.h>

void shift_text(const char *text, int k, char *out) {
    int i = 0;
    for (; text[i]; i++) {
        char ch = text[i];
        if (ch >= 'A' && ch <= 'Z') out[i] = (char)('A' + ((ch - 'A' + k) % 26 + 26) % 26);
        else if (ch >= 'a' && ch <= 'z') out[i] = (char)('a' + ((ch - 'a' + k) % 26 + 26) % 26);
        else out[i] = ch;
    }
    out[i] = '\0';
}

