#include <stdio.h>

int main(void) {
    int a, b, c;
    scanf("%d %d %d", &a, &b, &c);

    if (a <= 0 || b <= 0 || c <= 0 || a + b <= c || a + c <= b || b + c <= a) {
        printf("Not a triangle\n");
        return 0;
    }
    if (a == b && b == c) printf("Equilateral\n");
    else if (a == b || b == c || a == c) printf("Isosceles\n");
    else printf("Scalene\n");

    /* Sort the three sides so z is the largest. */
    int x = a, y = b, z = c, t;
    if (x > y) { t = x; x = y; y = t; }
    if (y > z) { t = y; y = z; z = t; }
    if (x > y) { t = x; x = y; y = t; }
    printf(x * x + y * y == z * z ? "Right-angled\n" : "Not right-angled\n");
    return 0;
}

