int main(void) {
    char words[128][64];
    int counts[128];
    int nwords = 0;
    char w[64];
    /* Distinct words in the order they first appear, like a Python dict. */
    while (scanf("%63s", w) == 1) {
        int i = 0;
        while (i < nwords && strcmp(words[i], w) != 0) i++;
        if (i == nwords) {
            strcpy(words[nwords], w);
            counts[nwords++] = 0;
        }
        counts[i]++;
    }

    int best = 0;
    for (int i = 1; i < nwords; i++) if (counts[i] > counts[best]) best = i;

    printf("Frequency: {");
    for (int i = 0; i < nwords; i++) printf(i ? ", '%s': %d" : "'%s': %d", words[i], counts[i]);
    printf("}\n");
    printf("Most frequent: %s\n", words[best]);
    return 0;
}

