import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Scanner;
import java.util.StringJoiner;

public class Main {
    public static void main(String[] args) {
        String[] words = new Scanner(System.in).nextLine().trim().split("\\s+");

        // LinkedHashMap keeps words in the order they first appear, like a Python dict.
        Map<String, Integer> freq = new LinkedHashMap<>();
        for (String w : words) freq.merge(w, 1, Integer::sum);

        String best = words[0];
        for (var entry : freq.entrySet()) if (entry.getValue() > freq.get(best)) best = entry.getKey();

        StringJoiner shown = new StringJoiner(", ", "{", "}");
        freq.forEach((w, count) -> shown.add("'" + w + "': " + count));
        System.out.println("Frequency: " + shown);
        System.out.println("Most frequent: " + best);
    }
}

