#include <stdio.h>
#include <stdlib.h>

static int read_line(int *out) {
    char line[4096];
    int n = 0;
    if (!fgets(line, sizeof line, stdin)) return 0;
    for (char *p = line; n < 128;) {
        int value, used;
        if (sscanf(p, "%d%n", &value, &used) != 1) break;
        out[n++] = value;
        p += used;
    }
    return n;
}

static int contains(const int *values, int n, int x) {
    for (int i = 0; i < n; i++) if (values[i] == x) return 1;
    return 0;
}

static int ascending(const void *a, const void *b) {
    return *(const int *)a - *(const int *)b;
}

/* Sorted, without duplicates, printed the way Python prints a list. */
static void print_sorted(const char *label, int *values, int n) {
    qsort(values, n, sizeof(int), ascending);
    printf("%s: [", label);
    int shown = 0;
    for (int i = 0; i < n; i++) {
        if (i > 0 && values[i] == values[i - 1]) continue;
        printf(shown++ ? ", %d" : "%d", values[i]);
    }
    printf("]\n");
}

int main(void) {
    int first[128], second[128];
    int n1 = read_line(first), n2 = read_line(second);

    int unique[128], nu = 0;
    for (int i = 0; i < n1; i++) if (!contains(unique, nu, first[i])) unique[nu++] = first[i];
    printf("Without duplicates: [");
    for (int i = 0; i < nu; i++) printf(i ? ", %d" : "%d", unique[i]);
    printf("]\n");

    int common[128], nc = 0, all[256], na = 0, only[128], no = 0;
    for (int i = 0; i < n1; i++) {
        all[na++] = first[i];
        if (contains(second, n2, first[i])) common[nc++] = first[i];
        else only[no++] = first[i];
    }
    for (int i = 0; i < n2; i++) all[na++] = second[i];
