void print(const std::string &label, const C &values) {
    std::cout << label << ": [";
    bool first = true;
    for (int x : values) {
        std::cout << (first ? "" : ", ") << x;
        first = false;
    }
    std::cout << "]\n";
}

int main() {
    std::vector<int> first = read_line(), second = read_line();

    std::set<int> seen;
    std::vector<int> unique;
    for (int x : first) if (seen.insert(x).second) unique.push_back(x);

    std::set<int> a(first.begin(), first.end()), b(second.begin(), second.end());
    std::set<int> common, all = a, only;
    for (int x : a) (b.count(x) ? common : only).insert(x);
    all.insert(b.begin(), b.end());

    print("Without duplicates", unique);
    print("Common", common);
    print("Union", all);
    print("Only in first", only);
}

