        union.addAll(b);
        only.removeAll(b);

        // Java collections print like Python lists: [1, 2, 3].
        System.out.println("Without duplicates: " + unique);
        System.out.println("Common: " + common);
        System.out.println("Union: " + union);
        System.out.println("Only in first: " + only);
    }
}

