        }
        int seen = 0;
        for (int m = 0; m < sizes[g]; m++) {
            if (strcmp(words[members[g][m]], words[w]) == 0) seen = 1;
        }
        if (!seen) members[g][sizes[g]++] = w;
    }

    for (int g = 0; g < ngroups; g++) {
        for (int m = 0; m < sizes[g]; m++) printf(m ? " %s" : "%s", words[members[g][m]]);
