public class Main {
    public static void main(String[] args) {
        String[] words = new Scanner(System.in).nextLine().trim().split("\\s+");

        // LinkedHashMap keeps groups in the order their first word appeared.
        Map<String, List<String>> groups = new LinkedHashMap<>();
        for (String w : words) {
            char[] letters = w.toCharArray();
            Arrays.sort(letters);
            List<String> members = groups.computeIfAbsent(new String(letters), key -> new ArrayList<>());
