#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int numbers[128], n = 0;
    while (n < 128 && scanf("%d", &numbers[n]) == 1) n++;

    printf("Odd squares: [");
    int shown = 0;
    for (int i = 0; i < n; i++) {
        if (numbers[i] % 2 != 0) printf(shown++ ? ", %d" : "%d", numbers[i] * numbers[i]);
    }
    printf("]\n");

    int even_sum = 0;
    for (int i = 0; i < n; i++) if (numbers[i] % 2 == 0) even_sum += numbers[i];
    printf("Sum of evens: %d\n", even_sum);

    /* Insertion sort is stable: equal absolute values keep their input order. */
    int sorted[128];
    for (int i = 0; i < n; i++) {
        int x = numbers[i], j = i;
        while (j > 0 && abs(sorted[j - 1]) > abs(x)) {
            sorted[j] = sorted[j - 1];
            j--;
        }
        sorted[j] = x;
    }
    printf("Sorted by absolute value: [");
    for (int i = 0; i < n; i++) printf(i ? ", %d" : "%d", sorted[i]);
    printf("]\n");
    return 0;
}

