#include <stdio.h>
#include <string.h>

/* 100 to the power 10 doesn't fit in 64 bits, so results use GCC's 128-bit integers. */
typedef __int128 big;

big add(big a, big b) { return a + b; }
big sub(big a, big b) { return a - b; }
big mul(big a, big b) { return a * b; }
big max_of(big a, big b) { return a > b ? a : b; }
big min_of(big a, big b) { return a < b ? a : b; }
big power(big a, big b) {
    big result = 1;
    for (big i = 0; i < b; i++) result *= a;
    return result;
}

big calculate(big a, big b, big (*operation)(big, big)) {
    return operation(a, b);
}

void print_big(big value) {
    char digits[64];
    int n = 0;
    int negative = value < 0;
    if (value == 0) digits[n++] = '0';
    while (value != 0) {
        int d = (int)(value % 10);
        digits[n++] = (char)('0' + (d < 0 ? -d : d));
        value /= 10;
    }
    if (negative) putchar('-');
    while (n > 0) putchar(digits[--n]);
}

int main(void) {
    const char *names[] = {"add", "sub", "mul", "max", "min", "pow"};
    big (*functions[])(big, big) = {add, sub, mul, max_of, min_of, power};

    long long a, b;
    scanf("%lld %lld", &a, &b);
    char name[64];
    while (scanf("%63s", name) == 1) {
        int found = -1;
        for (int i = 0; i < 6; i++) if (strcmp(name, names[i]) == 0) found = i;
        printf("%s: ", name);
        if (found < 0) {
            printf("Unsupported\n");
        } else {
            print_big(calculate(a, b, functions[found]));
            printf("\n");
