}

std::string to_string(big value) {
    if (value == 0) return "0";
    bool negative = value < 0;
    std::string digits;
    while (value != 0) {
        int d = static_cast<int>(value % 10);
        digits.insert(digits.begin(), static_cast<char>('0' + (d < 0 ? -d : d)));
        value /= 10;
    }
    return negative ? "-" + digits : digits;
}

