        {"sub", [](big a, big b) { return a - b; }},
        {"mul", [](big a, big b) { return a * b; }},
        {"max", [](big a, big b) { return a > b ? a : b; }},
        {"min", [](big a, big b) { return a < b ? a : b; }},
        {"pow", [](big a, big b) {
