/* Like Python's int(): optional sign, digits (underscores allowed between them), spaces around. */
static int to_int(const char *text, long long *out) {
    char digits[64];
    int n = 0, i = 0;
    while (isspace((unsigned char)text[i])) i++;
    if (text[i] == '+' || text[i] == '-') digits[n++] = text[i++];
    int count = 0;
    while (isdigit((unsigned char)text[i]) || (text[i] == '_' && count > 0 && isdigit((unsigned char)text[i + 1]))) {
        if (text[i] != '_') {
            if (n >= 40) return 0;
            digits[n++] = text[i];
            count++;
        }
        i++;
    }
    while (isspace((unsigned char)text[i])) i++;
    if (count == 0 || text[i] != '\0') return 0;
    digits[n] = '\0';
    *out = strtoll(digits, NULL, 10);
    return 1;
}

int main(void) {
    char first[128] = "", second[128] = "";
    fgets(first, sizeof first, stdin);
    fgets(second, sizeof second, stdin);

    long long a, b;
    if (!to_int(first, &a) || !to_int(second, &b)) printf("Invalid input\n");
