#include <optional>
#include <regex>
#include <string>

// Like Python's int(): optional sign, digits (underscores allowed between them), spaces around.
std::optional<long long> to_int(std::string text) {
    static const std::regex pattern(R"(^\s*[+-]?\d+(_\d+)*\s*$)");
    if (!std::regex_match(text, pattern)) return std::nullopt;
    std::string digits;
    for (char ch : text) if (ch != '_' && !std::isspace(static_cast<unsigned char>(ch))) digits += ch;
    try {
        return std::stoll(digits);
    } catch (...) {
        return std::nullopt;
    }
}

int main() {
    std::string first, second;
    std::getline(std::cin, first);
    std::getline(std::cin, second);

    auto a = to_int(first), b = to_int(second);
    if (!a || !b) std::cout << "Invalid input\n";
    else if (*b == 0) std::cout << "Cannot divide by zero\n";
    else std::printf("Result: %.2f\n", static_cast<double>(*a) / static_cast<double>(*b));
    std::cout << "Done\n";
}

