const lines = require("fs").readFileSync(0, "utf8").split("\n")

// A YYYY-MM-DD date, or null if it isn't a real date.
function parseDate(text) {
  const m = (text ?? "").trim().match(/^(\d{4})-(\d{2})-(\d{2})$/)
  if (!m) return null
  const [y, mo, d] = m.slice(1).map(Number)
  const date = new Date(Date.UTC(2000, mo - 1, d))
  date.setUTCFullYear(y)
  if (y < 1 || date.getUTCFullYear() !== y || date.getUTCMonth() !== mo - 1 || date.getUTCDate() !== d) return null
  return date
}

const d1 = parseDate(lines[0])
const d2 = parseDate(lines[1])
if (!d1 || !d2) {
  console.log("Invalid date")
} else {
  const names = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"]
  const iso = (d) => `${String(d.getUTCFullYear()).padStart(4, "0")}-${String(d.getUTCMonth() + 1).padStart(2, "0")}-${String(d.getUTCDate()).padStart(2, "0")}`
  console.log(`Weekday: ${names[d1.getUTCDay()]}`)
  console.log(`Days between: ${Math.abs(Math.round((d2 - d1) / 86400000))}`)
  console.log(`Later date: ${iso(d2 > d1 ? d2 : d1)}`)
}

