#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int is_leap(int y) { return y % 400 == 0 || (y % 4 == 0 && y % 100 != 0); }

/* Days since 1970-01-01 for a real date (works for any year). */
static long days_from_civil(int y, int m, int d) {
    y -= m <= 2;
    long era = (y >= 0 ? y : y - 399) / 400;
    long yoe = y - era * 400;
    long doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
    long doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    return era * 146097 + doe - 719468;
}

/* A YYYY-MM-DD date, or 0 if it isn't a real date. */
static int parse_date(char *text, int *y, int *m, int *d) {
    text[strcspn(text, "\r\n")] = '\0';
    while (*text == ' ') text++;
    char tail;
    int len = (int)strlen(text);
    while (len > 0 && text[len - 1] == ' ') text[--len] = '\0';
    if (len != 10 || text[4] != '-' || text[7] != '-') return 0;
    if (sscanf(text, "%4d-%2d-%2d%c", y, m, d, &tail) != 3) return 0;
    static const int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (*y < 1 || *m < 1 || *m > 12 || *d < 1) return 0;
    int limit = days[*m - 1] + (*m == 2 && is_leap(*y));
    return *d <= limit;
}

int main(void) {
    char first[64] = "", second[64] = "";
    fgets(first, sizeof first, stdin);
    fgets(second, sizeof second, stdin);
    int y1, m1, d1, y2, m2, d2;
    if (!parse_date(first, &y1, &m1, &d1) || !parse_date(second, &y2, &m2, &d2)) {
        printf("Invalid date\n");
        return 0;
    }
    long a = days_from_civil(y1, m1, d1), b = days_from_civil(y2, m2, d2);
    static const char *names[] = {"Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"};
