    printf("Weekday: %s\n", names[weekday]);
    printf("Days between: %ld\n", labs(b - a));
    if (b > a) printf("Later date: %04d-%02d-%02d\n", y2, m2, d2);
    else printf("Later date: %04d-%02d-%02d\n", y1, m1, d1);
    return 0;
}

