#include <chrono>
#include <cstdio>
#include <iostream>
#include <optional>
#include <regex>
#include <string>

using namespace std::chrono;

// A YYYY-MM-DD date, or nothing if it isn't a real date.
std::optional<year_month_day> parse_date(const std::string &text) {
    std::smatch m;
    static const std::regex pattern(R"(^\s*(\d{4})-(\d{2})-(\d{2})\s*$)");
    if (!std::regex_match(text, m, pattern)) return std::nullopt;
    year_month_day date{year{std::stoi(m[1])}, month{static_cast<unsigned>(std::stoi(m[2]))},
                        day{static_cast<unsigned>(std::stoi(m[3]))}};
    if (!date.ok() || date.year() < year{1}) return std::nullopt;
    return date;
}

int main() {
    std::string first, second;
    std::getline(std::cin, first);
    std::getline(std::cin, second);
    auto d1 = parse_date(first), d2 = parse_date(second);
    if (!d1 || !d2) {
        std::cout << "Invalid date\n";
        return 0;
    }

    static const char *names[] = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    sys_days a{*d1}, b{*d2};
    long between = (b - a).count();
    const year_month_day &later = b > a ? *d2 : *d1;

    std::cout << "Weekday: " << names[weekday{a}.c_encoding()] << "\n";
    std::cout << "Days between: " << (between < 0 ? -between : between) << "\n";
    std::printf("Later date: %04d-%02u-%02u\n", static_cast<int>(later.year()),
                static_cast<unsigned>(later.month()), static_cast<unsigned>(later.day()));
}

