import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import java.time.format.TextStyle;
import java.time.temporal.ChronoUnit;
import java.util.Locale;

public class Main {
    // Strict, so 2024-02-30 is an error rather than March 1st.
    static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd").withResolverStyle(ResolverStyle.STRICT);

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        LocalDate d1, d2;
        try {
            d1 = LocalDate.parse(in.readLine().strip(), ISO);
            d2 = LocalDate.parse(in.readLine().strip(), ISO);
        } catch (DateTimeParseException | NullPointerException e) {
            System.out.println("Invalid date");
            return;
        }
        System.out.println("Weekday: " + d1.getDayOfWeek().getDisplayName(TextStyle.FULL, Locale.ENGLISH));
        System.out.println("Days between: " + Math.abs(ChronoUnit.DAYS.between(d1, d2)));
        System.out.println("Later date: " + (d2.isAfter(d1) ? d2 : d1));
    }
}

