import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(in.readLine().strip());
        List<String> text = new ArrayList<>();
        for (int i = 0; i < n; i++) text.add(in.readLine());

        Path notes = Path.of("notes.txt");
        Files.write(notes, text);

        int lines = 0, words = 0, chars = 0;
        String longest = "";
        for (String line : Files.readAllLines(notes)) {
            lines++;
            if (!line.isBlank()) words += line.strip().split("\\s+").length;
            chars += line.codePointCount(0, line.length());
            if (line.length() > longest.length()) longest = line;
        }

        System.out.println("Lines: " + lines);
        System.out.println("Words: " + words);
        System.out.println("Characters: " + chars);
        System.out.println("Longest line: " + longest);
    }
}
